<?php
require dirname(__DIR__).'/app/bootstrap.php';
$id=query('id'); $comic=$catalog[$id] ?? null;
if (!in_array(parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH), ['/', '/index.php'], true)) $page='notfound';
if (!in_array($page,['home','comics','comic','reader','bookmarks','login','register','about'],true) || (in_array($page,['comic','reader'],true) && !$comic)) { http_response_code(404); $page='notfound'; }
if ($page==='reader' && !$comic['pages']) { http_response_code(404); $page='notfound'; }
$titles=['home'=>'Your next read starts here','comics'=>'Browse comics','bookmarks'=>'Your bookmarks','login'=>'Welcome back','register'=>'Create an account','about'=>'About this project','notfound'=>'Page not found'];
$title=$titles[$page] ?? $comic['title'];
function cards(array $items): void { ?>
<div class="grid"><?php foreach ($items as $key=>$item): ?><a class="card" href="/?page=comic&amp;id=<?=e($key)?>"><div class="cover"><img src="/assets/<?=e($item['cover'])?>" alt="<?=e($item['title'])?>" loading="lazy"><span><?= $item['pages'] ? 'Chapter '.$item['chapter'] : 'Coming soon' ?></span></div><h3><?=e($item['title'])?></h3><p><?=e(implode(' · ',$item['genres']))?></p></a><?php endforeach; ?></div>
<?php } ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Revista</title><link rel="stylesheet" href="/assets/app.css"></head><body class="<?= $page==='reader' ? 'reading' : '' ?>">
<header><div class="nav"><a class="brand" href="/">REVISTA<span>COMICS</span></a><nav aria-label="Main navigation"><a href="/" <?= $page==='home'?'aria-current="page"':'' ?>>Home</a><a href="/?page=comics" <?= $page==='comics'?'aria-current="page"':'' ?>>Comics</a><a href="/?page=bookmarks" <?= $page==='bookmarks'?'aria-current="page"':'' ?>>Bookmarks</a></nav><div class="account"><?php if ($user): ?><span class="username"><?=e($user['name'])?></span><form method="post"><?=csrf()?><button class="quiet" name="action" value="logout">Log out</button></form><?php else: ?><a href="/?page=login">Log in</a><a class="button small" href="/?page=register">Sign up</a><?php endif; ?></div></div></header>
<main>
<?php if ($flash): ?><p class="notice" role="status"><?=e($flash)?></p><?php endif; ?>
<?php if ($page==='home'): ?>
<div class="home-heading"><div><p class="eyebrow">YOUR PERSONAL MANHWA LIBRARY</p><h1>Discover. Read. Repeat.</h1></div><form class="quick-search" method="get"><input type="hidden" name="page" value="comics"><label class="sr-only" for="home-search">Search comics</label><input id="home-search" type="search" name="s" placeholder="Search your next read…"><button aria-label="Search comics">Search</button></form></div>
<section class="hero feature"><div class="feature-copy"><p class="eyebrow"><span class="status-dot"></span> FEATURED MANHWA</p><div class="tags"><a href="/?page=comics&amp;genre=Action">Action</a><a href="/?page=comics&amp;genre=Fantasy">Fantasy</a></div><h2>Revenge of the<br>Iron-Blooded<br><em>Sword Hound</em></h2><p>Your next read is waiting. Dive into the first chapter, or save it to your collection.</p><div class="actions"><a class="button" href="/?page=reader&amp;id=sword-hound">Read chapter 1 <span aria-hidden="true">↗</span></a><a class="button secondary" href="/?page=comic&amp;id=sword-hound">View series</a></div><div class="feature-meta"><span>MANHWA</span><span>CHAPTER 1</span><span><?=count($catalog['sword-hound']['pages'])?> IMAGES</span></div></div><img class="feature-art" src="/assets/manhwa/sword-hound/hero.jpg" alt="Revenge of the Iron-Blooded Sword Hound artwork"></section>
<section><div class="section-heading"><div><p class="eyebrow">PICK A STORY</p><h2>In your library <span class="count"><?=count($catalog)?></span></h2></div><a href="/?page=comics">Browse all ↗</a></div><?php cards($catalog); ?></section>
<section class="library-note"><div><p class="eyebrow">MAKE IT YOURS</p><h2>A place for your favorites.</h2><p>Save a series and find it again in your bookmarks.</p></div><a class="button secondary" href="/?page=bookmarks">Open bookmarks →</a></section>
<?php elseif ($page==='comics'): $search=trim(query('s')); $genre=query('genre'); $items=array_filter($catalog,fn($item)=>(!$search || stripos($item['title'],$search)!==false) && (!$genre || in_array($genre,$item['genres'],true))); ?>
<p class="eyebrow">THE COLLECTION</p><h1>Browse comics</h1><form class="filters" method="get"><input type="hidden" name="page" value="comics"><label>Search titles<input type="search" name="s" value="<?=e($search)?>" placeholder="Find a comic…"></label><label>Genre<select name="genre"><option value="">All genres</option><?php foreach (['Action','Adventure','Fantasy'] as $g): ?><option <?= $genre===$g?'selected':'' ?>><?=e($g)?></option><?php endforeach; ?></select></label><button>Search</button><a href="/?page=comics">Reset</a></form><p class="muted"><?=count($items)?> title<?=count($items)===1?'':'s'?> found</p><?php if ($items) cards($items); else echo '<div class="empty"><h2>No comics found</h2><p>Try a different title or genre.</p></div>'; ?>
<?php elseif ($page==='comic'): ?>
<a class="back" href="/?page=comics">← All comics</a><section class="detail"><img class="detail-cover" src="/assets/<?=e($comic['cover'])?>" alt="<?=e($comic['title'])?>"><div><p class="eyebrow">MANHWA</p><h1><?=e($comic['title'])?></h1><div class="tags"><?php foreach ($comic['genres'] as $g): ?><a href="/?page=comics&amp;genre=<?=e($g)?>"><?=e($g)?></a><?php endforeach; ?></div><p><?=e($comic['description'])?></p><div class="actions"><?php if ($comic['pages']): ?><a class="button" href="/?page=reader&amp;id=<?=e($id)?>">Read chapter <?=$comic['chapter']?> →</a><?php endif; ?><?php if ($user): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="remove" value="<?=in_array($id,$saved,true)?'1':'0'?>"><button class="secondary" name="action" value="bookmark"><?=in_array($id,$saved,true)?'Remove bookmark':'Save bookmark'?></button></form><?php else: ?><a class="button secondary" href="/?page=login">Log in to bookmark</a><?php endif; ?></div></div></section><section class="panel"><h2>Chapters</h2><?php if ($comic['pages']): ?><a class="chapter" href="/?page=reader&amp;id=<?=e($id)?>"><span>Chapter <?=$comic['chapter']?></span><span><?=count($comic['pages'])?> images →</span></a><?php else: ?><p class="muted">No chapters available yet.</p><?php endif; ?></section>
<?php elseif ($page==='reader'): ?>
<?php $wide=query('width')==='wide'; ?>
<div class="reader-heading"><a class="back" href="/?page=comic&amp;id=<?=e($id)?>">← Back to series</a><p class="eyebrow">CHAPTER <?=$comic['chapter']?></p><h1><?=e($comic['title'])?></h1><p><?=count($comic['pages'])?> images · Scroll to read</p></div>
<div class="reader-toolbar"><span>Chapter <?=$comic['chapter']?></span><div role="group" aria-label="Reader width"><a class="<?=!$wide?'selected':''?>" href="/?page=reader&amp;id=<?=e($id)?>" <?=!$wide?'aria-current="true"':''?>>Standard</a><a class="<?=$wide?'selected':''?>" href="/?page=reader&amp;id=<?=e($id)?>&amp;width=wide" <?=$wide?'aria-current="true"':''?>>Wide</a></div><a href="#reader-end">Jump to end ↓</a></div>
<div class="reader <?=$wide?'reader-wide':''?>"><?php foreach ($comic['pages'] as $i=>$image): ?><img src="/assets/<?=e(implode('/',array_map('rawurlencode',explode('/',$image))))?>" alt="Chapter <?=$comic['chapter']?>, image <?=$i+1?>" loading="<?=$i===0?'eager':'lazy'?>"><?php endforeach; ?></div>
<div class="reader-heading end-card" id="reader-end"><p class="eyebrow">YOU’RE ALL CAUGHT UP</p><h2>End of chapter <?=$comic['chapter']?></h2><p>That’s all the pages currently in this chapter.</p><a class="button" href="/?page=comic&amp;id=<?=e($id)?>">Back to series</a><a class="back" href="#">Back to top ↑</a></div>
<?php elseif ($page==='bookmarks'): ?>
<p class="eyebrow">YOUR LIBRARY</p><h1>Your bookmarks</h1><?php if (!$user): ?><div class="empty"><h2>Keep your favorites together</h2><p>Log in to save comics to your personal collection.</p><a class="button" href="/?page=login">Log in</a></div><?php elseif (!$saved): ?><div class="empty"><h2>Your collection starts here</h2><p>Open a comic and choose Save bookmark.</p><a class="button" href="/?page=comics">Browse comics</a></div><?php else: cards(array_intersect_key($catalog,array_flip($saved))); endif; ?>
<?php elseif ($page==='login' || $page==='register'): $register=$page==='register'; ?>
<section class="auth panel"><p class="eyebrow">REVISTA ACCOUNT</p><h1><?=e($title)?></h1><p class="muted"><?=$register?'Save your favorite comics in one place.':'Log in to see your saved comics.'?></p><?php if ($error): ?><p class="error" role="alert"><?=e($error)?></p><?php endif; ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="<?=$page?>"><?php if ($register): ?><label>Your name<input name="name" required maxlength="100" autocomplete="name" value="<?=e(field('name'))?>"></label><?php endif; ?><label>Email address<input type="email" name="email" required maxlength="254" autocomplete="email" value="<?=e(field('email'))?>"></label><label>Password<input type="password" name="password" required <?=$register?'minlength="8" maxlength="72"':''?> autocomplete="<?=$register?'new-password':'current-password'?>"></label><?php if ($register): ?><p class="hint">Use 8–72 bytes (ordinary letters and numbers use one byte each).</p><label>Confirm password<input type="password" name="confirm" required autocomplete="new-password"></label><?php endif; ?><button><?=$register?'Create account':'Log in'?></button></form><p><?=$register?'Already registered?':'New here?'?> <a href="/?page=<?=$register?'login':'register'?>"><?=$register?'Log in':'Create an account'?></a></p></section>
<?php elseif ($page==='about'): ?><section class="panel"><h1>About Revista</h1><p>A local comic-library project with browsing, an image reader, accounts, and personal bookmarks.</p><h2>Your data</h2><p>Names, email addresses, password hashes, and bookmarks are stored on this computer. This version sends no analytics and loads no third-party ads or scripts.</p><h2>Comic artwork</h2><p>The artwork and chapter images were supplied for this project and belong to their respective owners. The catalog is a demo, not a complete chapter library.</p></section>
<?php else: ?><div class="empty"><h1>Page not found</h1><p>This page or chapter is not available.</p><a class="button" href="/?page=comics">Browse comics</a></div><?php endif; ?>
</main><footer><a class="brand" href="/">REVISTA</a><p>A little space for your next adventure.</p><a href="/?page=about">About &amp; privacy</a></footer></body></html>
